/****************************************************************************
 * sensor_sim.h - 传感器模拟模块头文件
 *
 * 功能：模拟6轴IMU传感器数据（加速度计+陀螺仪）
 *       支持多种活动模式模拟（走路、跑步、跌倒等）
 ****************************************************************************/

#ifndef __SENSOR_SIM_H
#define __SENSOR_SIM_H

#include <stdint.h>
#include <stdbool.h>

/****************************************************************************
 * 定义
 ****************************************************************************/

// 传感器数据结构
typedef struct {
    float acc_x;      // X轴加速度 (g)
    float acc_y;      // Y轴加速度 (g)
    float acc_z;      // Z轴加速度 (g)
    float gyro_x;     // X轴角速度 (deg/s)
    float gyro_y;     // Y轴角速度 (deg/s)
    float gyro_z;     // Z轴角速度 (deg/s)
    uint64_t timestamp; // 时间戳 (ms)
} sensor_data_t;

// 活动模式枚举
typedef enum {
    ACTIVITY_STATIONARY = 0,  // 静止
    ACTIVITY_WALKING,         // 走路
    ACTIVITY_RUNNING,         // 跑步
    ACTIVITY_FALLING,         // 跌倒
    ACTIVITY_SITTING,         // 坐姿
    ACTIVITY_LYING,           // 躺姿
    ACTIVITY_CUSTOM,          // 自定义活动
    ACTIVITY_COUNT            // 活动总数
} activity_mode_t;

// 传感器配置结构
typedef struct {
    uint32_t sample_rate;     // 采样率 (Hz)
    float noise_level;        // 噪声水平
    float gravity;            // 重力加速度 (m/s²)
    bool enable_noise;        // 是否启用噪声
    bool enable_drift;        // 是否启用漂移
} sensor_config_t;

// 传感器状态结构
typedef struct {
    activity_mode_t current_activity;
    sensor_config_t config;
    uint64_t start_time;
    uint64_t sample_count;
    bool is_running;
} sensor_state_t;

/****************************************************************************
 * 公共函数
 ****************************************************************************/

// 初始化传感器模拟器
int sensor_sim_init(const sensor_config_t *config);

// 启动传感器模拟
int sensor_sim_start(void);

// 停止传感器模拟
int sensor_sim_stop(void);

// 获取传感器数据
int sensor_sim_read(sensor_data_t *data);

// 设置活动模式
int sensor_sim_set_activity(activity_mode_t activity);

// 获取当前活动模式
activity_mode_t sensor_sim_get_activity(void);

// 获取传感器状态
int sensor_sim_get_state(sensor_state_t *state);

// 重置传感器模拟器
int sensor_sim_reset(void);

// 销毁传感器模拟器
void sensor_sim_destroy(void);

// 生成模拟数据（用于测试）
int sensor_sim_generate_test_data(sensor_data_t *data, int count);

// 打印传感器数据（用于调试）
void sensor_sim_print_data(const sensor_data_t *data);

/****************************************************************************
 * 模拟数据生成函数
 ****************************************************************************/

// 生成静止状态数据
void generate_stationary(sensor_data_t *data);

// 生成走路状态数据
void generate_walking(sensor_data_t *data);

// 生成跑步状态数据
void generate_running(sensor_data_t *data);

// 生成跌倒状态数据
void generate_falling(sensor_data_t *data);

// 生成坐姿状态数据
void generate_sitting(sensor_data_t *data);

// 生成躺姿状态数据
void generate_lying(sensor_data_t *data);

// 添加噪声
void add_noise(sensor_data_t *data, float noise_level);

// 添加漂移
void add_drift(sensor_data_t *data, float drift_rate);

#endif /* __SENSOR_SIM_H */

/****************************************************************************
 * sensor_sim.c - 传感器模拟模块实现
 *
 * 功能：模拟6轴IMU传感器数据（加速度计+陀螺仪）
 *       支持多种活动模式模拟（走路、跑步、跌倒等）
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include "sensor_sim.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static sensor_state_t g_sensor_state = {0};
static uint64_t g_last_timestamp = 0;
static float g_phase = 0.0f;
static float g_fall_phase = 0.0f;

/****************************************************************************
 * 私有函数
 ****************************************************************************/

// 获取当前时间戳（毫秒）
static uint64_t get_timestamp_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

// 生成随机浮点数 [-1, 1]
static float random_float(void)
{
    return (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;
}

// 生成高斯噪声
static float gaussian_noise(float mean, float stddev)
{
    // Box-Muller变换
    float u1 = (float)rand() / (float)RAND_MAX;
    float u2 = (float)rand() / (float)RAND_MAX;
    float z = sqrtf(-2.0f * logf(u1)) * cosf(2.0f * M_PI * u2);
    return mean + stddev * z;
}

/****************************************************************************
 * 模拟数据生成函数
 ****************************************************************************/

void generate_stationary(sensor_data_t *data)
{
    // 静止状态：只有重力作用在Z轴
    data->acc_x = 0.0f;
    data->acc_y = 0.0f;
    data->acc_z = g_sensor_state.config.gravity;
    data->gyro_x = 0.0f;
    data->gyro_y = 0.0f;
    data->gyro_z = 0.0f;
}

void generate_walking(sensor_data_t *data)
{
    // 走路状态：周期性摆动
    float freq = 2.0f;  // 步频 2Hz
    float amp = 0.3f;   // 摆动幅度

    g_phase += 0.1f;
    if (g_phase > 2.0f * M_PI) {
        g_phase -= 2.0f * M_PI;
    }

    data->acc_x = amp * sinf(g_phase * freq);
    data->acc_y = amp * cosf(g_phase * freq);
    data->acc_z = g_sensor_state.config.gravity + 0.1f * sinf(g_phase * freq * 2);
    data->gyro_x = 10.0f * cosf(g_phase * freq);
    data->gyro_y = 10.0f * sinf(g_phase * freq);
    data->gyro_z = 5.0f * sinf(g_phase * freq * 0.5f);
}

void generate_running(sensor_data_t *data)
{
    // 跑步状态：更高频率和幅度
    float freq = 3.0f;  // 步频 3Hz
    float amp = 0.8f;   // 摆动幅度

    g_phase += 0.15f;
    if (g_phase > 2.0f * M_PI) {
        g_phase -= 2.0f * M_PI;
    }

    data->acc_x = amp * sinf(g_phase * freq);
    data->acc_y = amp * cosf(g_phase * freq);
    data->acc_z = g_sensor_state.config.gravity + 0.3f * sinf(g_phase * freq * 2);
    data->gyro_x = 25.0f * cosf(g_phase * freq);
    data->gyro_y = 25.0f * sinf(g_phase * freq);
    data->gyro_z = 15.0f * sinf(g_phase * freq * 0.5f);
}

void generate_falling(sensor_data_t *data)
{
    // 跌倒状态：失重 -> 撞击 -> 静止
    static int fall_step = 0;

    g_fall_phase += 0.1f;

    if (g_fall_phase < 1.0f) {
        // 阶段1：失重（0-1秒）
        data->acc_x = 0.0f;
        data->acc_y = 0.0f;
        data->acc_z = 0.1f;  // 接近零
        data->gyro_x = 0.0f;
        data->gyro_y = 0.0f;
        data->gyro_z = 0.0f;
    } else if (g_fall_phase < 1.2f) {
        // 阶段2：撞击（1-1.2秒）
        float impact = 5.0f * (1.2f - g_fall_phase) / 0.2f;
        data->acc_x = impact * 0.5f;
        data->acc_y = impact * 0.3f;
        data->acc_z = impact;
        data->gyro_x = 50.0f * (1.2f - g_fall_phase) / 0.2f;
        data->gyro_y = 30.0f * (1.2f - g_fall_phase) / 0.2f;
        data->gyro_z = 20.0f * (1.2f - g_fall_phase) / 0.2f;
    } else {
        // 阶段3：静止（1.2秒后）
        data->acc_x = 0.0f;
        data->acc_y = 0.0f;
        data->acc_z = g_sensor_state.config.gravity;
        data->gyro_x = 0.0f;
        data->gyro_y = 0.0f;
        data->gyro_z = 0.0f;

        // 重置跌倒阶段
        if (g_fall_phase > 3.0f) {
            g_fall_phase = 0.0f;
        }
    }
}

void generate_sitting(sensor_data_t *data)
{
    // 坐姿状态：相对稳定，轻微晃动
    data->acc_x = 0.05f * sinf(g_phase * 0.5f);
    data->acc_y = 0.05f * cosf(g_phase * 0.5f);
    data->acc_z = g_sensor_state.config.gravity + 0.02f * sinf(g_phase * 0.3f);
    data->gyro_x = 2.0f * sinf(g_phase * 0.2f);
    data->gyro_y = 2.0f * cosf(g_phase * 0.2f);
    data->gyro_z = 1.0f * sinf(g_phase * 0.1f);

    g_phase += 0.05f;
}

void generate_lying(sensor_data_t *data)
{
    // 躺姿状态：接近静止
    data->acc_x = 0.02f * sinf(g_phase * 0.1f);
    data->acc_y = g_sensor_state.config.gravity + 0.01f * sinf(g_phase * 0.05f);
    data->acc_z = 0.01f * cosf(g_phase * 0.1f);
    data->gyro_x = 0.5f * sinf(g_phase * 0.05f);
    data->gyro_y = 0.5f * cosf(g_phase * 0.05f);
    data->gyro_z = 0.3f * sinf(g_phase * 0.03f);

    g_phase += 0.02f;
}

void add_noise(sensor_data_t *data, float noise_level)
{
    if (noise_level <= 0.0f) {
        return;
    }

    data->acc_x += gaussian_noise(0.0f, noise_level);
    data->acc_y += gaussian_noise(0.0f, noise_level);
    data->acc_z += gaussian_noise(0.0f, noise_level);
    data->gyro_x += gaussian_noise(0.0f, noise_level * 10.0f);
    data->gyro_y += gaussian_noise(0.0f, noise_level * 10.0f);
    data->gyro_z += gaussian_noise(0.0f, noise_level * 10.0f);
}

void add_drift(sensor_data_t *data, float drift_rate)
{
    if (drift_rate <= 0.0f) {
        return;
    }

    static float drift_x = 0.0f;
    static float drift_y = 0.0f;
    static float drift_z = 0.0f;

    drift_x += gaussian_noise(0.0f, drift_rate);
    drift_y += gaussian_noise(0.0f, drift_rate);
    drift_z += gaussian_noise(0.0f, drift_rate);

    // 限制漂移范围
    drift_x = fmaxf(-0.5f, fminf(0.5f, drift_x));
    drift_y = fmaxf(-0.5f, fminf(0.5f, drift_y));
    drift_z = fmaxf(-0.5f, fminf(0.5f, drift_z));

    data->acc_x += drift_x;
    data->acc_y += drift_y;
    data->acc_z += drift_z;
}

/****************************************************************************
 * 公共函数实现
 ****************************************************************************/

int sensor_sim_init(const sensor_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    // 初始化状态
    memset(&g_sensor_state, 0, sizeof(sensor_state_t));

    // 设置配置
    g_sensor_state.config = *config;

    // 设置默认值
    if (g_sensor_state.config.sample_rate == 0) {
        g_sensor_state.config.sample_rate = 100;  // 默认100Hz
    }
    if (g_sensor_state.config.gravity == 0.0f) {
        g_sensor_state.config.gravity = 9.81f;    // 默认重力加速度
    }

    // 初始化随机数种子
    srand((unsigned int)time(NULL));

    // 重置相位
    g_phase = 0.0f;
    g_fall_phase = 0.0f;

    printf("Sensor simulator initialized: sample_rate=%u Hz, gravity=%.2f m/s²\n",
           g_sensor_state.config.sample_rate, g_sensor_state.config.gravity);

    return 0;
}

int sensor_sim_start(void)
{
    if (g_sensor_state.is_running) {
        return -1;  // 已经在运行
    }

    g_sensor_state.is_running = true;
    g_sensor_state.start_time = get_timestamp_ms();
    g_sensor_state.sample_count = 0;
    g_sensor_state.current_activity = ACTIVITY_STATIONARY;

    printf("Sensor simulator started\n");
    return 0;
}

int sensor_sim_stop(void)
{
    if (!g_sensor_state.is_running) {
        return -1;  // 未在运行
    }

    g_sensor_state.is_running = false;
    printf("Sensor simulator stopped: total samples=%llu\n",
           (unsigned long long)g_sensor_state.sample_count);

    return 0;
}

int sensor_sim_read(sensor_data_t *data)
{
    if (data == NULL || !g_sensor_state.is_running) {
        return -1;
    }

    // 生成基础数据
    switch (g_sensor_state.current_activity) {
        case ACTIVITY_STATIONARY:
            generate_stationary(data);
            break;
        case ACTIVITY_WALKING:
            generate_walking(data);
            break;
        case ACTIVITY_RUNNING:
            generate_running(data);
            break;
        case ACTIVITY_FALLING:
            generate_falling(data);
            break;
        case ACTIVITY_SITTING:
            generate_sitting(data);
            break;
        case ACTIVITY_LYING:
            generate_lying(data);
            break;
        default:
            generate_stationary(data);
            break;
    }

    // 添加噪声和漂移
    if (g_sensor_state.config.enable_noise) {
        add_noise(data, g_sensor_state.config.noise_level);
    }
    if (g_sensor_state.config.enable_drift) {
        add_drift(data, 0.001f);
    }

    // 设置时间戳
    data->timestamp = get_timestamp_ms();
    g_last_timestamp = data->timestamp;
    g_sensor_state.sample_count++;

    return 0;
}

int sensor_sim_set_activity(activity_mode_t activity)
{
    if (activity >= ACTIVITY_COUNT) {
        return -1;
    }

    g_sensor_state.current_activity = activity;

    // 重置跌倒阶段
    if (activity == ACTIVITY_FALLING) {
        g_fall_phase = 0.0f;
    }

    printf("Activity changed to: %d\n", activity);
    return 0;
}

activity_mode_t sensor_sim_get_activity(void)
{
    return g_sensor_state.current_activity;
}

int sensor_sim_get_state(sensor_state_t *state)
{
    if (state == NULL) {
        return -1;
    }

    *state = g_sensor_state;
    return 0;
}

int sensor_sim_reset(void)
{
    g_phase = 0.0f;
    g_fall_phase = 0.0f;
    g_last_timestamp = 0;
    g_sensor_state.sample_count = 0;
    g_sensor_state.current_activity = ACTIVITY_STATIONARY;

    printf("Sensor simulator reset\n");
    return 0;
}

void sensor_sim_destroy(void)
{
    sensor_sim_stop();
    memset(&g_sensor_state, 0, sizeof(sensor_state_t));
    printf("Sensor simulator destroyed\n");
}

int sensor_sim_generate_test_data(sensor_data_t *data, int count)
{
    if (data == NULL || count <= 0) {
        return -1;
    }

    // 临时启动传感器
    bool was_running = g_sensor_state.is_running;
    if (!was_running) {
        sensor_sim_start();
    }

    // 生成测试数据
    for (int i = 0; i < count; i++) {
        sensor_sim_read(&data[i]);
    }

    // 恢复状态
    if (!was_running) {
        sensor_sim_stop();
    }

    return count;
}

void sensor_sim_print_data(const sensor_data_t *data)
{
    if (data == NULL) {
        return;
    }

    printf("Sensor Data [t=%llu ms]:\n", (unsigned long long)data->timestamp);
    printf("  Acc:  X=%.3f, Y=%.3f, Z=%.3f g\n",
           data->acc_x, data->acc_y, data->acc_z);
    printf("  Gyro: X=%.3f, Y=%.3f, Z=%.3f deg/s\n",
           data->gyro_x, data->gyro_y, data->gyro_z);
}

/****************************************************************************
 * 主函数（用于独立测试）
 ****************************************************************************/

#ifdef SENSOR_SIM_TEST
int main(int argc, char *argv[])
{
    printf("Sensor Simulator Test\n");
    printf("====================\n");

    // 配置传感器
    sensor_config_t config = {
        .sample_rate = 100,
        .noise_level = 0.05f,
        .gravity = 9.81f,
        .enable_noise = true,
        .enable_drift = true
    };

    // 初始化
    if (sensor_sim_init(&config) != 0) {
        printf("Failed to initialize sensor simulator\n");
        return 1;
    }

    // 启动
    if (sensor_sim_start() != 0) {
        printf("Failed to start sensor simulator\n");
        return 1;
    }

    // 测试不同活动模式
    activity_mode_t activities[] = {
        ACTIVITY_STATIONARY,
        ACTIVITY_WALKING,
        ACTIVITY_RUNNING,
        ACTIVITY_FALLING,
        ACTIVITY_SITTING,
        ACTIVITY_LYING
    };

    const char *activity_names[] = {
        "Stationary",
        "Walking",
        "Running",
        "Falling",
        "Sitting",
        "Lying"
    };

    for (int i = 0; i < 6; i++) {
        printf("\nTesting %s mode:\n", activity_names[i]);
        sensor_sim_set_activity(activities[i]);

        // 生成10个样本
        sensor_data_t data[10];
        sensor_sim_generate_test_data(data, 10);

        // 打印第一个和最后一个
        printf("  First sample:\n");
        sensor_sim_print_data(&data[0]);
        printf("  Last sample:\n");
        sensor_sim_print_data(&data[9]);
    }

    // 清理
    sensor_sim_destroy();

    printf("\nTest completed successfully!\n");
    return 0;
}
#endif

/****************************************************************************
 * ai_engine.h - AI推理引擎头文件
 *
 * 功能：集成TensorFlow Lite Micro，提供端侧AI推理能力
 *       支持姿态识别、跌倒检测等AI功能
 ****************************************************************************/

#ifndef __AI_ENGINE_H
#define __AI_ENGINE_H

#include <stdint.h>
#include <stdbool.h>

/****************************************************************************
 * 定义
 ****************************************************************************/

// AI模型类型
typedef enum {
    MODEL_POSE_RECOGNITION = 0,  // 姿态识别模型
    MODEL_FALL_DETECTION,        // 跌倒检测模型
    MODEL_ANOMALY_DETECTION,     // 异常检测模型
    MODEL_CUSTOM,                // 自定义模型
    MODEL_COUNT                  // 模型总数
} ai_model_type_t;

// AI推理结果
typedef struct {
    float confidence;           // 置信度 [0, 1]
    int32_t prediction;         // 预测类别
    float scores[10];           // 各类别得分（最多10类）
    uint64_t inference_time;    // 推理时间 (ms)
    bool is_valid;              // 结果是否有效
} ai_result_t;

// AI引擎配置
typedef struct {
    ai_model_type_t model_type;
    int32_t input_size;         // 输入数据大小
    int32_t output_size;        // 输出数据大小
    bool use_quantization;      // 是否使用量化
    bool use_gpu;               // 是否使用GPU加速
    int32_t num_threads;        // 推理线程数
} ai_config_t;

// AI引擎状态
typedef struct {
    bool is_initialized;
    bool is_running;
    ai_config_t config;
    uint64_t total_inferences;
    uint64_t total_time;
    float avg_inference_time;
} ai_state_t;

/****************************************************************************
 * 公共函数
 ****************************************************************************/

// 初始化AI引擎
int ai_engine_init(const ai_config_t *config);

// 加载模型
int ai_engine_load_model(const char *model_path);

// 卸载模型
int ai_engine_unload_model(void);

// 执行推理
int ai_engine_inference(const float *input_data, int32_t input_size,
                       ai_result_t *result);

// 获取引擎状态
int ai_engine_get_state(ai_state_t *state);

// 重置统计信息
void ai_engine_reset_stats(void);

// 销毁AI引擎
void ai_engine_destroy(void);

// 模拟推理（用于测试）
int ai_engine_simulate_inference(ai_result_t *result);

// 获取模型信息
int ai_engine_get_model_info(char *info, int32_t max_len);

/****************************************************************************
 * 模型管理函数
 ****************************************************************************/

// 注册自定义模型
int ai_engine_register_model(ai_model_type_t type, const char *model_path);

// 获取已注册模型列表
int ai_engine_list_models(char *list, int32_t max_len);

// 检查模型是否存在
bool ai_engine_model_exists(ai_model_type_t type);

/****************************************************************************
 * 调试和测试函数
 ****************************************************************************/

// 打印推理结果
void ai_engine_print_result(const ai_result_t *result);

// 打印引擎状态
void ai_engine_print_state(void);

// 运行基准测试
int ai_engine_benchmark(int32_t iterations);

// 验证引擎功能
bool ai_engine_validate(void);

#endif /* __AI_ENGINE_H */

/****************************************************************************
 * ai_engine.c - AI推理引擎实现
 *
 * 功能：集成TensorFlow Lite Micro，提供端侧AI推理能力
 *       支持姿态识别、跌倒检测等AI功能
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include "ai_engine.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static ai_state_t g_ai_state = {0};
static float g_model_weights[1000] = {0};  // 模拟模型权重
static bool g_model_loaded = false;

/****************************************************************************
 * 私有函数
 ****************************************************************************/

// 获取当前时间戳（毫秒）
static uint64_t get_timestamp_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

// 模拟简单的神经网络推理
static int simulate_neural_network(const float *input, int32_t input_size,
                                   float *output, int32_t output_size)
{
    // 简化的前向传播模拟
    // 实际应用中会调用TensorFlow Lite Micro API

    // 初始化输出
    for (int32_t i = 0; i < output_size; i++) {
        output[i] = 0.0f;
    }

    // 模拟权重矩阵乘法
    for (int32_t i = 0; i < output_size; i++) {
        for (int32_t j = 0; j < input_size && j < 100; j++) {
            output[i] += input[j] * g_model_weights[i * 100 + j];
        }
        // 添加偏置
        output[i] += g_model_weights[output_size * 100 + i];
        // 应用激活函数（softmax近似）
        output[i] = expf(output[i]) / (1.0f + expf(output[i]));
    }

    return 0;
}

// 初始化模型权重
static void init_model_weights(void)
{
    srand((unsigned int)time(NULL));
    for (int32_t i = 0; i < 1000; i++) {
        g_model_weights[i] = (float)rand() / (float)RAND_MAX * 0.1f - 0.05f;
    }
    g_model_loaded = true;
}

/****************************************************************************
 * 公共函数实现
 ****************************************************************************/

int ai_engine_init(const ai_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    // 初始化状态
    memset(&g_ai_state, 0, sizeof(ai_state_t));

    // 设置配置
    g_ai_state.config = *config;

    // 设置默认值
    if (g_ai_state.config.num_threads == 0) {
        g_ai_state.config.num_threads = 1;
    }

    // 初始化模型权重
    init_model_weights();

    g_ai_state.is_initialized = true;

    printf("AI engine initialized: model_type=%d, input_size=%d, output_size=%d\n",
           g_ai_state.config.model_type,
           g_ai_state.config.input_size,
           g_ai_state.config.output_size);

    return 0;
}

int ai_engine_load_model(const char *model_path)
{
    if (model_path == NULL) {
        return -1;
    }

    // 模拟加载模型
    printf("Loading model from: %s\n", model_path);

    // 实际应用中会调用 TensorFlow Lite Micro API
    // interpreter = tflite::MicroInterpreter(...);
    // interpreter->AllocateTensors();

    g_ai_state.is_running = true;
    printf("Model loaded successfully\n");

    return 0;
}

int ai_engine_unload_model(void)
{
    if (!g_ai_state.is_running) {
        return -1;
    }

    // 模拟卸载模型
    g_ai_state.is_running = false;
    printf("Model unloaded\n");

    return 0;
}

int ai_engine_inference(const float *input_data, int32_t input_size,
                       ai_result_t *result)
{
    if (input_data == NULL || result == NULL || !g_ai_state.is_initialized) {
        return -1;
    }

    uint64_t start_time = get_timestamp_ms();

    // 模拟推理过程
    float output[10] = {0};
    int32_t output_size = g_ai_state.config.output_size;
    if (output_size > 10) {
        output_size = 10;
    }

    // 执行模拟推理
    simulate_neural_network(input_data, input_size, output, output_size);

    // 处理结果
    result->prediction = 0;
    result->confidence = 0.0f;
    result->is_valid = true;

    for (int32_t i = 0; i < output_size; i++) {
        result->scores[i] = output[i];
        if (output[i] > result->confidence) {
            result->confidence = output[i];
            result->prediction = i;
        }
    }

    uint64_t end_time = get_timestamp_ms();
    result->inference_time = end_time - start_time;

    // 更新统计信息
    g_ai_state.total_inferences++;
    g_ai_state.total_time += result->inference_time;
    g_ai_state.avg_inference_time = (float)g_ai_state.total_time /
                                   (float)g_ai_state.total_inferences;

    return 0;
}

int ai_engine_get_state(ai_state_t *state)
{
    if (state == NULL) {
        return -1;
    }

    *state = g_ai_state;
    return 0;
}

void ai_engine_reset_stats(void)
{
    g_ai_state.total_inferences = 0;
    g_ai_state.total_time = 0;
    g_ai_state.avg_inference_time = 0.0f;
    printf("AI engine stats reset\n");
}

void ai_engine_destroy(void)
{
    ai_engine_unload_model();
    memset(&g_ai_state, 0, sizeof(ai_state_t));
    g_model_loaded = false;
    printf("AI engine destroyed\n");
}

int ai_engine_simulate_inference(ai_result_t *result)
{
    if (result == NULL) {
        return -1;
    }

    // 生成随机输入数据
    float input_data[600];  // 1秒 * 100Hz * 6轴
    for (int32_t i = 0; i < 600; i++) {
        input_data[i] = (float)rand() / (float)RAND_MAX * 2.0f - 1.0f;
    }

    return ai_engine_inference(input_data, 600, result);
}

