int ai_engine_benchmark(int32_t iterations)
{
    if (iterations <= 0) {
        return -1;
    }

    printf("Running AI engine benchmark: %d iterations\n", iterations);

    uint64_t total_time = 0;
    for (int32_t i = 0; i < iterations; i++) {
        ai_result_t result;
        ai_engine_simulate_inference(&result);
        total_time += result.inference_time;
    }

    float avg_time = (float)total_time / (float)iterations;
    float throughput = 1000.0f / avg_time;  // 每秒推理次数

    printf("Benchmark Results:\n");
    printf("  Total Time: %llu ms\n", (unsigned long long)total_time);
    printf("  Average Time: %.2f ms\n", avg_time);
    printf("  Throughput: %.2f inferences/sec\n", throughput);

    return 0;
}

bool ai_engine_validate(void)
{
    if (!g_ai_state.is_initialized) {
        printf("AI engine not initialized\n");
        return false;
    }

    // 测试推理功能
    ai_result_t result;
    if (ai_engine_simulate_inference(&result) != 0) {
        printf("AI engine inference failed\n");
        return false;
    }

    if (!result.is_valid) {
        printf("AI engine produced invalid result\n");
        return false;
    }

    printf("AI engine validation passed\n");
    return true;
}

