/****************************************************************************
 * posture_recognition.c - 体态识别算法实现
 *
 * 功能：基于传感器数据和AI推理结果，进行姿态识别和跌倒检测
 *       支持多种姿态分类和异常检测
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include "posture_recognition.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static posture_state_t g_posture_state = {0};

/****************************************************************************
 * 私有函数
 ****************************************************************************/

// 获取当前时间戳（毫秒）
static uint64_t get_timestamp_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

// 更新滑动窗口
static void update_window(const sensor_data_t *data)
{
    if (g_posture_state.window_count < 100) {
        g_posture_state.window[g_posture_state.window_count] = *data;
        g_posture_state.window_count++;
    } else {
        // 滑动窗口
        memmove(&g_posture_state.window[0],
                &g_posture_state.window[1],
                sizeof(sensor_data_t) * 99);
        g_posture_state.window[99] = *data;
    }
    g_posture_state.window_index = (g_posture_state.window_index + 1) % 100;
}

/****************************************************************************
 * 特征提取函数实现
 ****************************************************************************/

float calculate_acc_magnitude(const sensor_data_t *data)
{
    if (data == NULL) {
        return 0.0f;
    }
    return sqrtf(data->acc_x * data->acc_x +
                 data->acc_y * data->acc_y +
                 data->acc_z * data->acc_z);
}

float calculate_gyro_magnitude(const sensor_data_t *data)
{
    if (data == NULL) {
        return 0.0f;
    }
    return sqrtf(data->gyro_x * data->gyro_x +
                 data->gyro_y * data->gyro_y +
                 data->gyro_z * data->gyro_z);
}

void calculate_orientation(const sensor_data_t *data,
                          float *roll, float *pitch, float *yaw)
{
    if (data == NULL || roll == NULL || pitch == NULL || yaw == NULL) {
        return;
    }

    // 简化的姿态角计算
    // 实际应用中会使用更复杂的算法（如互补滤波、卡尔曼滤波）
    *roll = atan2f(data->acc_y, data->acc_z) * 180.0f / M_PI;
    *pitch = atan2f(-data->acc_x,
                    sqrtf(data->acc_y * data->acc_y +
                          data->acc_z * data->acc_z)) * 180.0f / M_PI;
    *yaw = 0.0f;  // 仅使用加速度计无法准确计算偏航角
}

void calculate_statistics(const sensor_data_t *window, int32_t size,
                         float *mean, float *stddev, float *max_val)
{
    if (window == NULL || size <= 0 || mean == NULL ||
        stddev == NULL || max_val == NULL) {
        return;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float max_mag = 0.0f;

    for (int32_t i = 0; i < size; i++) {
        float mag = calculate_acc_magnitude(&window[i]);
        sum += mag;
        sum_sq += mag * mag;
        if (mag > max_mag) {
            max_mag = mag;
        }
    }

    *mean = sum / (float)size;
    *stddev = sqrtf(sum_sq / (float)size - (*mean) * (*mean));
    *max_val = max_mag;
}

void calculate_frequency_features(const sensor_data_t *window, int32_t size,
                                 float *dominant_freq, float *energy)
{
    if (window == NULL || size <= 0 || dominant_freq == NULL || energy == NULL) {
        return;
    }

    // 简化的频域特征计算
    // 实际应用中会使用FFT
    float total_energy = 0.0f;
    float max_energy = 0.0f;
    int32_t max_index = 0;

    for (int32_t k = 0; k < size / 2; k++) {
        float real = 0.0f;
        float imag = 0.0f;

        for (int32_t n = 0; n < size; n++) {
            float angle = 2.0f * M_PI * k * n / (float)size;
            float mag = calculate_acc_magnitude(&window[n]);
            real += mag * cosf(angle);
            imag -= mag * sinf(angle);
        }

        float energy_k = real * real + imag * imag;
        total_energy += energy_k;

        if (energy_k > max_energy) {
            max_energy = energy_k;
            max_index = k;
        }
    }

    *dominant_freq = (float)max_index / (float)size * 100.0f;  // 假设100Hz采样率
    *energy = total_energy;
}

/****************************************************************************
 * 检测算法函数实现
 ****************************************************************************/

bool detect_fall(const sensor_data_t *window, int32_t size)
{
    if (window == NULL || size <= 0) {
        return false;
    }

    // 跌倒检测算法：
    // 1. 检测加速度幅值突变
    // 2. 检测失重状态
    // 3. 检测撞击后静止

    float max_acc = 0.0f;
    float min_acc = 100.0f;
    float last_acc = 0.0f;

    for (int32_t i = 0; i < size; i++) {
        float acc_mag = calculate_acc_magnitude(&window[i]);

        if (acc_mag > max_acc) {
            max_acc = acc_mag;
        }
        if (acc_mag < min_acc) {
            min_acc = acc_mag;
        }

        last_acc = acc_mag;
    }

    // 检测条件：
    // 1. 最大加速度 > 3g（撞击）
    // 2. 最小加速度 < 0.5g（失重）
    // 3. 最后加速度接近1g（静止）

    bool impact_detected = (max_acc > 3.0f * 9.81f);
    bool weightlessness_detected = (min_acc < 0.5f * 9.81f);
    bool still_detected = (fabsf(last_acc - 9.81f) < 0.5f * 9.81f);

    return (impact_detected && weightlessness_detected && still_detected);
}

bool detect_abnormal_posture(const sensor_data_t *window, int32_t size)
{
    if (window == NULL || size <= 0) {
        return false;
    }

    // 异常姿态检测：
    // 检测长时间保持非正常姿态

    float roll, pitch, yaw;
    int32_t abnormal_count = 0;

    for (int32_t i = 0; i < size; i++) {
        calculate_orientation(&window[i], &roll, &pitch, &yaw);

        // 检测异常姿态：倾斜角度过大
        if (fabsf(roll) > 45.0f || fabsf(pitch) > 45.0f) {
            abnormal_count++;
        }
    }

    // 如果超过80%的时间处于异常姿态，则认为异常
    return (abnormal_count > size * 0.8f);
}

posture_type_t classify_posture(const sensor_data_t *window, int32_t size)
{
    if (window == NULL || size <= 0) {
        return POSTURE_UNKNOWN;
    }

    // 姿态分类算法：
    // 基于统计特征和规则进行分类

    float mean_acc, stddev_acc, max_acc;
    calculate_statistics(window, size, &mean_acc, &stddev_acc, &max_acc);

    float dominant_freq, energy;
    calculate_frequency_features(window, size, &dominant_freq, &energy);

    // 分类规则
    if (stddev_acc < 0.1f * 9.81f) {
        // 加速度变化小，可能是静止或躺姿
        float last_roll, last_pitch, last_yaw;
        calculate_orientation(&window[size - 1], &last_roll, &last_pitch, &last_yaw);

        if (fabsf(last_pitch) > 60.0f) {
            return POSTURE_LYING;  // 躺姿
        } else {
            return POSTURE_STANDING;  // 站立
        }
    } else if (dominant_freq > 1.5f && dominant_freq < 3.5f) {
        // 步频范围，可能是走路
        if (max_acc > 2.0f * 9.81f) {
            return POSTURE_RUNNING;  // 跑步
        } else {
            return POSTURE_WALKING;  // 走路
        }
    } else if (mean_acc > 1.2f * 9.81f && mean_acc < 1.5f * 9.81f) {
        // 坐姿特征
        return POSTURE_SITTING;
    } else {
        // 默认站立
        return POSTURE_STANDING;
    }
}

float calculate_risk_score(const posture_result_t *result)
{
    if (result == NULL) {
        return 0.0f;
    }

    float risk = 0.0f;

    // 根据姿态类型计算风险
    switch (result->posture) {
        case POSTURE_FALLING:
            risk = 1.0f;  // 跌倒中，最高风险
            break;
        case POSTURE_FALLEN:
            risk = 0.9f;  // 已跌倒，高风险
            break;
        case POSTURE_ABNORMAL:
            risk = 0.7f;  // 异常姿态，中高风险
            break;
        case POSTURE_RUNNING:
            risk = 0.3f;  // 跑步，低风险
            break;
        case POSTURE_WALKING:
            risk = 0.2f;  // 走路，较低风险
            break;
        case POSTURE_SITTING:
            risk = 0.1f;  // 坐姿，低风险
            break;
        case POSTURE_STANDING:
        case POSTURE_LYING:
            risk = 0.05f; // 站立/躺姿，最低风险
            break;
        default:
            risk = 0.5f;  // 未知姿态，中等风险
            break;
    }

    // 根据置信度调整风险
    risk *= (1.0f + (1.0f - result->confidence) * 0.5f);

    return risk;
}

float calculate_confidence(const posture_result_t *result)
{
    if (result == NULL) {
        return 0.0f;
    }

    // 简化的置信度计算
    // 实际应用中会基于模型输出和统计特征综合计算
    float base_confidence = result->confidence;

    // 根据姿态类型调整置信度
    if (result->posture == POSTURE_FALLING || result->posture == POSTURE_FALLEN) {
        // 跌倒检测通常置信度较高
        base_confidence = fmaxf(base_confidence, 0.8f);
    }

    return base_confidence;
}

/****************************************************************************
 * 公共函数实现
 ****************************************************************************/

int posture_init(const posture_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    // 初始化状态
    memset(&g_posture_state, 0, sizeof(posture_state_t));

    // 设置配置
    g_posture_state.config = *config;

    // 设置默认值
    if (g_posture_state.config.fall_threshold == 0.0f) {
        g_posture_state.config.fall_threshold = 3.0f * 9.81f;
    }
    if (g_posture_state.config.abnormal_threshold == 0.0f) {
        g_posture_state.config.abnormal_threshold = 45.0f;
    }
    if (g_posture_state.config.window_size == 0) {
        g_posture_state.config.window_size = 100;
    }

    g_posture_state.is_initialized = true;

    printf("Posture recognition initialized: fall_threshold=%.2f, abnormal_threshold=%.2f\n",
           g_posture_state.config.fall_threshold,
           g_posture_state.config.abnormal_threshold);

    return 0;
}

int posture_start(void)
{
    if (g_posture_state.is_running) {
        return -1;  // 已经在运行
    }

    g_posture_state.is_running = true;
    g_posture_state.window_count = 0;
    g_posture_state.window_index = 0;
    g_posture_state.total_frames = 0;
    g_posture_state.fall_count = 0;
    g_posture_state.abnormal_count = 0;

    printf("Posture recognition started\n");
    return 0;
}

int posture_stop(void)
{
    if (!g_posture_state.is_running) {
        return -1;  // 未在运行
    }

    g_posture_state.is_running = false;
    printf("Posture recognition stopped: total_frames=%llu, falls=%llu, abnormal=%llu\n",
           (unsigned long long)g_posture_state.total_frames,
           (unsigned long long)g_posture_state.fall_count,
           (unsigned long long)g_posture_state.abnormal_count);

    return 0;
}

int posture_process_sensor_data(const sensor_data_t *data,
                               posture_result_t *result)
{
    if (data == NULL || result == NULL || !g_posture_state.is_running) {
        return -1;
    }

    // 更新滑动窗口
    update_window(data);

    // 初始化结果
    memset(result, 0, sizeof(posture_result_t));
    result->timestamp = data->timestamp;

    // 检测跌倒
    if (detect_fall(g_posture_state.window, g_posture_state.window_count)) {
        result->is_falling_detected = true;
        result->posture = POSTURE_FALLING;
        result->safety_level = SAFETY_EMERGENCY;
        g_posture_state.fall_count++;
    }
    // 检测异常姿态
    else if (detect_abnormal_posture(g_posture_state.window,
                                    g_posture_state.window_count)) {
        result->is_abnormal_detected = true;
        result->posture = POSTURE_ABNORMAL;
        result->safety_level = SAFETY_DANGER;
        g_posture_state.abnormal_count++;
    }
    // 正常姿态分类
    else {
        result->posture = classify_posture(g_posture_state.window,
                                          g_posture_state.window_count);

        // 根据姿态设置安全等级
        switch (result->posture) {
            case POSTURE_RUNNING:
                result->safety_level = SAFETY_WARNING;
                break;
            case POSTURE_WALKING:
            case POSTURE_STANDING:
            case POSTURE_SITTING:
            case POSTURE_LYING:
                result->safety_level = SAFETY_NORMAL;
                break;
            default:
                result->safety_level = SAFETY_WARNING;
                break;
        }
    }

    // 计算置信度和风险评分
    result->confidence = calculate_confidence(result);
    result->risk_score = calculate_risk_score(result);

    // 更新状态
    g_posture_state.total_frames++;
    g_posture_state.last_result = *result;

    return 0;
}

posture_type_t posture_get_current(void)
{
    return g_posture_state.last_result.posture;
}

safety_level_t posture_get_safety_level(void)
{
    return g_posture_state.last_result.safety_level;
}

int posture_get_state(posture_state_t *state)
{
    if (state == NULL) {
        return -1;
    }

    *state = g_posture_state;
    return 0;
}

int posture_set_config(const posture_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    g_posture_state.config = *config;
    printf("Posture config updated\n");
    return 0;
}

int posture_reset(void)
{
    g_posture_state.window_count = 0;
    g_posture_state.window_index = 0;
    g_posture_state.total_frames = 0;
    g_posture_state.fall_count = 0;
    g_posture_state.abnormal_count = 0;
    memset(&g_posture_state.last_result, 0, sizeof(posture_result_t));

    printf("Posture recognition reset\n");
    return 0;
}

void posture_destroy(void)
{
    posture_stop();
    memset(&g_posture_state, 0, sizeof(posture_state_t));
    printf("Posture recognition destroyed\n");
}

void posture_print_result(const posture_result_t *result)
{
    if (result == NULL) {
        return;
    }

    const char *posture_names[] = {
        "Unknown", "Standing", "Walking", "Running",
        "Sitting", "Lying", "Falling", "Fallen", "Abnormal"
    };

    const char *safety_names[] = {
        "Normal", "Warning", "Danger", "Emergency"
    };

    printf("Posture Result [t=%llu ms]:\n", (unsigned long long)result->timestamp);
    printf("  Posture: %s (confidence=%.3f)\n",
           posture_names[result->posture], result->confidence);
    printf("  Safety: %s\n", safety_names[result->safety_level]);
    printf("  Risk Score: %.3f\n", result->risk_score);
    printf("  Falling Detected: %s\n", result->is_falling_detected ? "Yes" : "No");
    printf("  Abnormal Detected: %s\n", result->is_abnormal_detected ? "Yes" : "No");
}

void posture_print_state(void)
{
    printf("Posture Recognition State:\n");
    printf("  Initialized: %s\n", g_posture_state.is_initialized ? "Yes" : "No");
    printf("  Running: %s\n", g_posture_state.is_running ? "Yes" : "No");
    printf("  Total Frames: %llu\n",
           (unsigned long long)g_posture_state.total_frames);
    printf("  Fall Count: %llu\n",
           (unsigned long long)g_posture_state.fall_count);
    printf("  Abnormal Count: %llu\n",
           (unsigned long long)g_posture_state.abnormal_count);
    printf("  Window Count: %d\n", g_posture_state.window_count);
}

int posture_run_test_cases(void)
{
    printf("Running posture recognition test cases...\n");

    // 测试1：静止状态
    printf("\nTest 1: Stationary state\n");
    sensor_data_t stationary_data[10];
    for (int i = 0; i < 10; i++) {
        stationary_data[i].acc_x = 0.0f;
        stationary_data[i].acc_y = 0.0f;
        stationary_data[i].acc_z = 9.81f;
        stationary_data[i].gyro_x = 0.0f;
        stationary_data[i].gyro_y = 0.0f;
        stationary_data[i].gyro_z = 0.0f;
        stationary_data[i].timestamp = i * 10;
    }

    posture_result_t result;
    for (int i = 0; i < 10; i++) {
        posture_process_sensor_data(&stationary_data[i], &result);
    }
    posture_print_result(&result);

    // 测试2：跌倒状态
    printf("\nTest 2: Falling state\n");
    sensor_data_t falling_data[10];
    for (int i = 0; i < 10; i++) {
        if (i < 3) {
            // 失重阶段
            falling_data[i].acc_x = 0.0f;
            falling_data[i].acc_y = 0.0f;
            falling_data[i].acc_z = 0.5f;
        } else if (i < 5) {
            // 撞击阶段
            falling_data[i].acc_x = 2.0f;
            falling_data[i].acc_y = 1.0f;
            falling_data[i].acc_z = 4.0f;
        } else {
            // 静止阶段
            falling_data[i].acc_x = 0.0f;
            falling_data[i].acc_y = 0.0f;
            falling_data[i].acc_z = 9.81f;
        }
        falling_data[i].gyro_x = 0.0f;
        falling_data[i].gyro_y = 0.0f;
        falling_data[i].gyro_z = 0.0f;
        falling_data[i].timestamp = i * 10 + 100;
    }

    for (int i = 0; i < 10; i++) {
        posture_process_sensor_data(&falling_data[i], &result);
    }
    posture_print_result(&result);

    printf("\nTest cases completed!\n");
    return 0;
}

bool posture_validate(void)
{
    if (!g_posture_state.is_initialized) {
        printf("Posture recognition not initialized\n");
        return false;
    }

    // 测试基本功能
    sensor_data_t test_data = {0};
    test_data.acc_x = 0.0f;
    test_data.acc_y = 0.0f;
    test_data.acc_z = 9.81f;
    test_data.timestamp = get_timestamp_ms();

    posture_result_t result;
    if (posture_process_sensor_data(&test_data, &result) != 0) {
        printf("Posture recognition processing failed\n");
        return false;
    }

    printf("Posture recognition validation passed\n");
    return true;
}

