#include "../posture_recognition/posture_recognition.h"

/****************************************************************************
 * 定义
 ****************************************************************************/

// 监控状态
typedef enum {
    MONITOR_IDLE = 0,           // 空闲
    MONITOR_ACTIVE,             // 活跃监控
    MONITOR_WARNING,            // 预警状态
    MONITOR_EMERGENCY,          // 紧急状态
    MONITOR_COUNT
} monitor_state_t;

// 警报类型
typedef enum {
    ALERT_NONE = 0,             // 无警报
    ALERT_POSTURE_WARNING,      // 姿态预警
    ALERT_FALL_DETECTED,        // 检测到跌倒
    ALERT_ABNORMAL_POSTURE,     // 异常姿态
    ALERT_INACTIVITY,           // 长时间静止
    ALERT_BATTERY_LOW,          // 电量低
    ALERT_SENSOR_ERROR,         // 传感器错误
    ALERT_COUNT
} alert_type_t;

// 警报信息
typedef struct {
    alert_type_t type;          // 警报类型
    safety_level_t level;       // 安全等级
    char message[256];          // 警报消息
    uint64_t timestamp;         // 时间戳
    bool is_active;             // 是否激活
    bool auto_dismiss;          // 是否自动解除
    uint32_t dismiss_timeout;   // 解除超时（秒）
} alert_info_t;

// 监控配置
typedef struct {
    bool enable_fall_detection;     // 启用跌倒检测
    bool enable_abnormal_detection; // 启用异常检测
    bool enable_inactivity_alert;   // 启用静止预警
    uint32_t inactivity_timeout;    // 静止预警超时（秒）
    uint32_t emergency_timeout;     // 紧急状态超时（秒）
    bool auto_call_for_help;        // 自动求救
    bool enable_sound_alert;        // 启用声音警报
    bool enable_vibration_alert;    // 启用振动警报
} monitor_config_t;

// 监控统计
typedef struct {
    uint64_t total_alerts;          // 总警报数
    uint64_t fall_alerts;           // 跌倒警报数
    uint64_t abnormal_alerts;       // 异常警报数
    uint64_t inactivity_alerts;     // 静止警报数
    uint64_t total_monitoring_time; // 总监控时间（秒）
    uint64_t emergency_responded;   // 紧急响应次数
} monitor_stats_t;

// 监控状态结构
typedef struct {
    bool is_initialized;
    bool is_running;
    monitor_state_t state;
    monitor_config_t config;
    monitor_stats_t stats;
    alert_info_t current_alert;
