/****************************************************************************
 * safety_monitor.c - 安全监控服务层实现
 *
 * 功能：处理安全预警、紧急呼叫、状态管理等
 *       提供完整的安全监控解决方案
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "safety_monitor.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static monitor_state_t g_monitor_state = {0};
static alert_callback_t g_alert_callback = NULL;
static state_callback_t g_state_callback = NULL;

/****************************************************************************
 * 私有函数
 ****************************************************************************/

// 获取当前时间戳（毫秒）
static uint64_t get_timestamp_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

// 获取当前时间戳（秒）
static uint64_t get_timestamp_sec(void)
{
    return get_timestamp_ms() / 1000;
}

// 设置监控状态
static void set_monitor_state(monitor_state_t new_state)
{
    if (g_monitor_state.state != new_state) {
        monitor_state_t old_state = g_monitor_state.state;
        g_monitor_state.state = new_state;

        // 触发状态变化回调
        if (g_state_callback != NULL) {
            g_state_callback(old_state, new_state);
        }

        printf("Monitor state changed: %d -> %d\n", old_state, new_state);
    }
}

// 触发警报
static void trigger_alert(alert_type_t type, safety_level_t level,
                         const char *message, bool auto_dismiss,
                         uint32_t dismiss_timeout)
{
    // 设置警报信息
    g_monitor_state.current_alert.type = type;
    g_monitor_state.current_alert.level = level;
    g_monitor_state.current_alert.timestamp = get_timestamp_ms();
    g_monitor_state.current_alert.is_active = true;
    g_monitor_state.current_alert.auto_dismiss = auto_dismiss;
    g_monitor_state.current_alert.dismiss_timeout = dismiss_timeout;

    if (message != NULL) {
        strncpy(g_monitor_state.current_alert.message, message,
                sizeof(g_monitor_state.current_alert.message) - 1);
    }

    // 更新统计
    g_monitor_state.stats.total_alerts++;
    safety_monitor_record_alert(type);

    // 触发警报回调
    if (g_alert_callback != NULL) {
        g_alert_callback(&g_monitor_state.current_alert);
    }

    // 根据安全等级设置监控状态
    if (level >= SAFETY_EMERGENCY) {
        set_monitor_state(MONITOR_EMERGENCY);
    } else if (level >= SAFETY_DANGER) {
        set_monitor_state(MONITOR_WARNING);
    }

    printf("Alert triggered: type=%d, level=%d, message=%s\n",
           type, level, message);
}

/****************************************************************************
 * 公共函数实现
 ****************************************************************************/

int safety_monitor_init(const monitor_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    // 初始化状态
    memset(&g_monitor_state, 0, sizeof(monitor_state_t));

    // 设置配置
    g_monitor_state.config = *config;

    // 设置默认值
    if (g_monitor_state.config.inactivity_timeout == 0) {
        g_monitor_state.config.inactivity_timeout = 300;  // 5分钟
    }
    if (g_monitor_state.config.emergency_timeout == 0) {
        g_monitor_state.config.emergency_timeout = 60;    // 1分钟
    }

    g_monitor_state.is_initialized = true;
    g_monitor_state.state = MONITOR_IDLE;

    printf("Safety monitor initialized\n");
    printf("  Fall detection: %s\n", config->enable_fall_detection ? "Enabled" : "Disabled");
    printf("  Abnormal detection: %s\n", config->enable_abnormal_detection ? "Enabled" : "Disabled");
    printf("  Inactivity alert: %s (timeout=%u s)\n",
           config->enable_inactivity_alert ? "Enabled" : "Disabled",
           config->inactivity_timeout);

    return 0;
}

int safety_monitor_start(void)
{
    if (g_monitor_state.is_running) {
        return -1;  // 已经在运行
    }

    g_monitor_state.is_running = true;
    g_monitor_state.start_time = get_timestamp_ms();
    g_monitor_state.last_activity_time = get_timestamp_sec();

    set_monitor_state(MONITOR_ACTIVE);

    printf("Safety monitor started\n");
    return 0;
}

int safety_monitor_stop(void)
{
    if (!g_monitor_state.is_running) {
        return -1;  // 未在运行
    }

    g_monitor_state.is_running = false;
    set_monitor_state(MONITOR_IDLE);

    // 解除所有警报
    safety_monitor_dismiss_alert();

    printf("Safety monitor stopped\n");
    return 0;
}

int safety_monitor_process_posture(const posture_result_t *posture)
{
    if (posture == NULL || !g_monitor_state.is_running) {
        return -1;
    }

    // 保存最后的体态结果
    g_monitor_state.last_posture = *posture;

    // 更新活动时间
    if (posture->posture != POSTURE_UNKNOWN) {
        g_monitor_state.last_activity_time = get_timestamp_sec();
    }

    // 检查是否需要发出警报
    if (safety_monitor_check_alert_condition(posture)) {
        // 根据体态结果触发相应的警报
        if (posture->is_falling_detected) {
            trigger_alert(ALERT_FALL_DETECTED, SAFETY_EMERGENCY,
                         "检测到跌倒！正在发送求救信号...", false, 0);
            g_monitor_state.stats.fall_alerts++;
        } else if (posture->is_abnormal_detected) {
            trigger_alert(ALERT_ABNORMAL_POSTURE, SAFETY_DANGER,
                         "检测到异常姿态！", true, 30);
            g_monitor_state.stats.abnormal_alerts++;
        } else if (posture->safety_level >= SAFETY_DANGER) {
            trigger_alert(ALERT_POSTURE_WARNING, posture->safety_level,
                         "姿态预警！", true, 15);
        }
    }

    // 检查静止预警
    safety_monitor_update_inactivity_check(get_timestamp_sec());

    return 0;
}

monitor_state_t safety_monitor_get_state(void)
{
    return g_monitor_state.state;
}

int safety_monitor_get_current_alert(alert_info_t *alert)
{
    if (alert == NULL) {
        return -1;
    }

    *alert = g_monitor_state.current_alert;
    return 0;
}

int safety_monitor_get_stats(monitor_stats_t *stats)
{
    if (stats == NULL) {
        return -1;
    }

    // 计算总监控时间
    if (g_monitor_state.is_running) {
        g_monitor_state.stats.total_monitoring_time =
            (get_timestamp_ms() - g_monitor_state.start_time) / 1000;
    }

    *stats = g_monitor_state.stats;
    return 0;
}

int safety_monitor_set_config(const monitor_config_t *config)
{
    if (config == NULL) {
        return -1;
    }

    g_monitor_state.config = *config;
    printf("Safety monitor config updated\n");
    return 0;
}

int safety_monitor_trigger_alert(alert_type_t type, const char *message)
{
    if (message == NULL) {
        return -1;
    }

    safety_level_t level = SAFETY_WARNING;
    bool auto_dismiss = true;
    uint32_t dismiss_timeout = 15;

    switch (type) {
        case ALERT_FALL_DETECTED:
            level = SAFETY_EMERGENCY;
            auto_dismiss = false;
            dismiss_timeout = 0;
            break;
        case ALERT_ABNORMAL_POSTURE:
            level = SAFETY_DANGER;
            dismiss_timeout = 30;
            break;
        case ALERT_INACTIVITY:
            level = SAFETY_WARNING;
            dismiss_timeout = 60;
            break;
        case ALERT_BATTERY_LOW:
            level = SAFETY_WARNING;
            dismiss_timeout = 120;
            break;
        default:
            break;
    }

    trigger_alert(type, level, message, auto_dismiss, dismiss_timeout);
    return 0;
}

int safety_monitor_dismiss_alert(void)
{
    if (!g_monitor_state.current_alert.is_active) {
        return -1;  // 没有活跃的警报
    }

    printf("Dismissing alert: type=%d\n", g_monitor_state.current_alert.type);

    // 清除警报
    memset(&g_monitor_state.current_alert, 0, sizeof(alert_info_t));

    // 恢复监控状态
    if (g_monitor_state.is_running) {
        set_monitor_state(MONITOR_ACTIVE);
    }

    return 0;
}

int safety_monitor_confirm_emergency(void)
{
    if (g_monitor_state.state != MONITOR_EMERGENCY) {
        return -1;  // 不在紧急状态
    }

    g_monitor_state.stats.emergency_responded++;
    printf("Emergency confirmed by user\n");

    // 停止自动求救（如果启用）
    g_monitor_state.config.auto_call_for_help = false;

    return 0;
}

int safety_monitor_cancel_emergency(void)
{
    if (g_monitor_state.state != MONITOR_EMERGENCY) {
        return -1;  // 不在紧急状态
    }

    safety_monitor_dismiss_alert();
    printf("Emergency cancelled by user\n");

    return 0;
}

int safety_monitor_reset(void)
{
    memset(&g_monitor_state.stats, 0, sizeof(monitor_stats_t));
    memset(&g_monitor_state.current_alert, 0, sizeof(alert_info_t));
    memset(g_monitor_state.alert_history, 0, sizeof(g_monitor_state.alert_history));
    g_monitor_state.alert_history_index = 0;
    g_monitor_state.last_activity_time = get_timestamp_sec();

    printf("Safety monitor reset\n");
    return 0;
}

void safety_monitor_destroy(void)
{
    safety_monitor_stop();
    safety_monitor_unregister_callbacks();
    memset(&g_monitor_state, 0, sizeof(monitor_state_t));
    printf("Safety monitor destroyed\n");
}

int safety_monitor_register_alert_callback(alert_callback_t callback)
{
