    return 0;
}

int safety_monitor_unregister_callbacks(void)
{
    g_alert_callback = NULL;
    g_state_callback = NULL;
    printf("Callbacks unregistered\n");
    return 0;
}

bool safety_monitor_check_alert_condition(const posture_result_t *posture)
{
    if (posture == NULL) {
        return false;
    }

    // 检查跌倒检测
    if (g_monitor_state.config.enable_fall_detection && posture->is_falling_detected) {
        return true;
    }

    // 检查异常姿态检测
    if (g_monitor_state.config.enable_abnormal_detection && posture->is_abnormal_detected) {
        return true;
    }

    // 检查安全等级
    if (posture->safety_level >= SAFETY_DANGER) {
        return true;
    }

    return false;
}

void safety_monitor_update_inactivity_check(uint64_t current_time)
{
    if (!g_monitor_state.config.enable_inactivity_alert) {
        return;
    }

    uint64_t inactive_duration = current_time - g_monitor_state.last_activity_time;

    if (inactive_duration >= g_monitor_state.config.inactivity_timeout) {
        // 检查是否已经发出过静止预警
        bool already_alerted = false;
        for (int32_t i = 0; i < 100; i++) {
            if (g_monitor_state.alert_history[i] == ALERT_INACTIVITY) {
                already_alerted = true;
                break;
            }
        }

        if (!already_alerted) {
            trigger_alert(ALERT_INACTIVITY, SAFETY_WARNING,
                         "长时间未活动！", true, 60);
            g_monitor_state.stats.inactivity_alerts++;
        }
    }
}

void safety_monitor_handle_emergency(void)
{
    if (g_monitor_state.state != MONITOR_EMERGENCY) {
        return;
    }

    // 模拟紧急处理
    printf("EMERGENCY HANDLING:\n");
    printf("  1. Recording current location...\n");
    printf("  2. Notifying emergency contacts...\n");
    printf("  3. Sending distress signal...\n");

    if (g_monitor_state.config.auto_call_for_help) {
        printf("  4. Auto-calling for help...\n");
        // 实际应用中会调用通信模块发送求救信号
    }
}

void safety_monitor_record_alert(alert_type_t type)
{
    // 记录警报到历史
    g_monitor_state.alert_history[g_monitor_state.alert_history_index] = type;
    g_monitor_state.alert_history_index =
        (g_monitor_state.alert_history_index + 1) % 100;
}

void safety_monitor_generate_alert_message(alert_type_t type, char *message, int32_t max_len)
{
    if (message == NULL || max_len <= 0) {
        return;
    }

    switch (type) {
        case ALERT_FALL_DETECTED:
            snprintf(message, max_len, "检测到跌倒！正在发送求救信号...");
            break;
        case ALERT_ABNORMAL_POSTURE:
            snprintf(message, max_len, "检测到异常姿态！");
            break;
        case ALERT_INACTIVITY:
            snprintf(message, max_len, "长时间未活动！");
            break;
        case ALERT_BATTERY_LOW:
            snprintf(message, max_len, "电量低！");
            break;
        case ALERT_SENSOR_ERROR:
            snprintf(message, max_len, "传感器错误！");
            break;
        default:
            snprintf(message, max_len, "未知警报！");
            break;
    }
}

