// 解析命令行参数
static int parse_args(int argc, char *argv[], int *duration, int *sample_rate, int *verbose)
{
    int opt;
    while ((opt = getopt(argc, argv, "m:d:r:vh")) != -1) {
        switch (opt) {
            case 'm':
                g_demo_mode = atoi(optarg);
                if (g_demo_mode < 0 || g_demo_mode > 2) {
                    printf("Invalid mode: %d (should be 0, 1, or 2)\n", g_demo_mode);
                    return -1;
                }
                break;
            case 'd':
                *duration = atoi(optarg);
                if (*duration <= 0) {
                    printf("Invalid duration: %d\n", *duration);
                    return -1;
                }
                break;
            case 'r':
                *sample_rate = atoi(optarg);
                if (*sample_rate <= 0 || *sample_rate > 1000) {
                    printf("Invalid sample rate: %d\n", *sample_rate);
                    return -1;
                }
                break;
            case 'v':
                *verbose = 1;
                break;
            case 'h':
                print_usage(argv[0]);
                exit(0);
            default:
                print_usage(argv[0]);
                return -1;
        }
    }
    return 0;
}

