    activity_mode_t demo_activities[] = {
        ACTIVITY_STATIONARY,
        ACTIVITY_WALKING,
        ACTIVITY_RUNNING,
        ACTIVITY_FALLING,
        ACTIVITY_SITTING,
        ACTIVITY_LYING
    };

    const char *activity_names[] = {
        "Stationary", "Walking", "Running",
        "Falling", "Sitting", "Lying"
    };

    int activity_count = sizeof(demo_activities) / sizeof(demo_activities[0]);
    int activity_duration = duration / activity_count;

    uint64_t start_time = get_timestamp_ms();
    int current_activity = 0;

    while (g_running) {
        uint64_t elapsed = (get_timestamp_ms() - start_time) / 1000;

        // 检查是否需要切换活动模式
        if (elapsed >= (current_activity + 1) * activity_duration) {
            current_activity++;
            if (current_activity >= activity_count) {
                break;  // 演示结束
            }

            printf("\n=== Switching to: %s ===\n", activity_names[current_activity]);
            sensor_sim_set_activity(demo_activities[current_activity]);
        }

        // 读取传感器数据
        sensor_data_t sensor_data;
        if (sensor_sim_read(&sensor_data) == 0) {
            // 执行AI推理
            ai_result_t ai_result;
            ai_engine_simulate_inference(&ai_result);

            // 处理体态识别
            posture_result_t posture_result;
            posture_process_sensor_data(&sensor_data, &posture_result);

            // 处理安全监控
            safety_monitor_process_posture(&posture_result);

            // 每秒打印一次状态
            if (elapsed % 1 == 0) {
                printf("\r[%.1fs] Posture: %s, Safety: %s, Risk: %.2f",
                       (float)elapsed,
                       posture_result.posture == POSTURE_STANDING ? "Standing" :
                       posture_result.posture == POSTURE_WALKING ? "Walking" :
                       posture_result.posture == POSTURE_RUNNING ? "Running" :
                       posture_result.posture == POSTURE_FALLING ? "Falling" :
                       posture_result.posture == POSTURE_SITTING ? "Sitting" :
                       posture_result.posture == POSTURE_LYING ? "Lying" : "Unknown",
                       posture_result.safety_level == SAFETY_NORMAL ? "Normal" :
                       posture_result.safety_level == SAFETY_WARNING ? "Warning" :
                       posture_result.safety_level == SAFETY_DANGER ? "Danger" : "Emergency",
                       posture_result.risk_score);
                fflush(stdout);
            }
        }

        // 控制采样率
        usleep(1000000 / 100);  // 100Hz
    }

    printf("\n\n");
}

// 测试模式
static void run_test_mode(void)
{
    printf("\nRunning in TEST mode...\n\n");

    // 运行各模块测试
    printf("=== Testing Sensor Simulator ===\n");
    sensor_sim_start();
    sensor_sim_set_activity(ACTIVITY_WALKING);
    sensor_data_t test_data[10];
    sensor_sim_generate_test_data(test_data, 10);
    sensor_sim_print_data(&test_data[0]);
    sensor_sim_stop();

    printf("\n=== Testing AI Engine ===\n");
    ai_engine_validate();
    ai_engine_benchmark(100);

    printf("\n=== Testing Posture Recognition ===\n");
    posture_start();
    posture_run_test_cases();
    posture_stop();

    printf("\n=== Testing Safety Monitor ===\n");
    safety_monitor_start();
    safety_monitor_run_test_cases();
    safety_monitor_stop();

    printf("\n=== All Tests Completed ===\n\n");
}

// 正常模式
static void run_normal_mode(int duration, int verbose)
{
    printf("\nRunning in NORMAL mode for %d seconds...\n", duration);
    printf("Press Ctrl+C to stop early\n\n");

    uint64_t start_time = get_timestamp_ms();
    int sample_count = 0;

    while (g_running) {
        uint64_t elapsed = (get_timestamp_ms() - start_time) / 1000;

        if (elapsed >= duration) {
            break;
        }

        // 读取传感器数据
        sensor_data_t sensor_data;
        if (sensor_sim_read(&sensor_data) == 0) {
            sample_count++;

            // 执行AI推理
            ai_result_t ai_result;
            ai_engine_simulate_inference(&ai_result);

            // 处理体态识别
            posture_result_t posture_result;
            posture_process_sensor_data(&sensor_data, &posture_result);

            // 处理安全监控
            safety_monitor_process_posture(&posture_result);

            // 详细输出
            if (verbose && sample_count % 100 == 0) {
                printf("\n--- Sample %d [t=%llu ms] ---\n",
                       sample_count, (unsigned long long)sensor_data.timestamp);
                sensor_sim_print_data(&sensor_data);
                posture_print_result(&posture_result);
            }

            // 简要输出
            if (!verbose && sample_count % 1000 == 0) {
                printf("\r[%.1fs] Samples: %d, Posture: %d, Safety: %d",
                       (float)elapsed, sample_count,
                       posture_result.posture, posture_result.safety_level);
                fflush(stdout);
            }
        }

        // 控制采样率
        usleep(1000000 / 100);  // 100Hz
    }

    printf("\n\n");
}

// 获取时间戳
static uint64_t get_timestamp_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
    int duration = 60;  // 默认运行60秒
    int sample_rate = 100;  // 默认采样率100Hz
    int verbose = 0;

    // 打印欢迎信息
    print_welcome();

    // 解析命令行参数
    if (parse_args(argc, argv, &duration, &sample_rate, &verbose) != 0) {
        return 1;
    }

    // 设置信号处理
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // 初始化所有模块
    if (init_all_modules(sample_rate) != 0) {
        printf("Failed to initialize modules\n");
        return 1;
    }

    // 启动所有模块
    if (start_all_modules() != 0) {
        printf("Failed to start modules\n");
        destroy_all_modules();
        return 1;
    }

    // 根据模式运行
    switch (g_demo_mode) {
        case 0:
            run_normal_mode(duration, verbose);
            break;
        case 1:
            run_demo_mode(duration);
            break;
        case 2:
            run_test_mode();
            break;
        default:
            printf("Invalid mode: %d\n", g_demo_mode);
            break;
    }

    // 停止所有模块
    stop_all_modules();

    // 打印最终统计
    printf("\n=== Final Statistics ===\n");
    posture_print_state();
    safety_monitor_print_stats();
    ai_engine_print_state();

    // 销毁所有模块
    destroy_all_modules();

    printf("\nSafePosture terminated normally\n");
    return 0;
}

