/**
 * 常量定义
 * posture-guard/constants.js
 */

// 体态类型
const POSTURE_TYPE = {
  NORMAL: 'NORMAL',
  HEAD_DOWN: 'HEAD_DOWN',       // 低头前倾
  SEDENTARY: 'SEDENTARY',       // 久坐伏案
  CROSS_LEGS: 'CROSS_LEGS',    // 跷二郎腿
};

// 体态类型中文名
const POSTURE_LABELS = {
  [POSTURE_TYPE.NORMAL]: '正常',
  [POSTURE_TYPE.HEAD_DOWN]: '低头前倾',
  [POSTURE_TYPE.SEDENTARY]: '久坐伏案',
  [POSTURE_TYPE.CROSS_LEGS]: '跷二郎腿',
};

// 提醒冷却时间（毫秒）
const REMINDER_COOLDOWN_MS = 5 * 60 * 1000; // 5分钟

// 滑动窗口大小（采样点数，50Hz × 2秒 = 100）
const WINDOW_SIZE = 100;

// 采样频率
const SAMPLE_RATE_HZ = 50;

// 判定阈值
const THRESHOLDS = {
  headDown: { pitchAngle: 30, durationMin: 10, confidence: 0.85 },
  sedentary: { accMag: 0.1, pitchAngle: 15, durationMin: 45, confidence: 0.80 },
  crossLegs: { roll波动: 0.15, zJitter: 0.1, durationMin: 5, confidence: 0.75 },
};

// 加密等级
const CRYPTO_LEVEL = {
  L1: 'L1', // 普通体态统计
  L2: 'L2', // 心率等核心隐私
};

// 数据生命周期（天）
const LIFECYCLE = {
  postureStats: 30,
  heartRateData: 7,
  securityLogs: 90,
};

// 文件名
const FILE_KEYS = {
  postureStats: 'posture_stats',
  heartRate: 'heart_rate',
  stepCount: 'step_count',
  securityLog: 'security_log',
  settings: 'settings',
};

// 脱敏策略
const DESENSITIZE = {
  TIME_GRANULARITY: 'hour',
  HR_INTERVAL: 5,
  GRID_SIZE: 500,
};

// Mock场景
const MOCK_SCENARIO = {
  NORMAL: 'normal',
  HEAD_DOWN: 'headDown',
  SEDENTARY: 'sedentary',
  CROSS_LEGS: 'crossLegs',
};

module.exports = {
  POSTURE_TYPE,
  POSTURE_LABELS,
  REMINDER_COOLDOWN_MS,
  WINDOW_SIZE,
  SAMPLE_RATE_HZ,
  THRESHOLDS,
  CRYPTO_LEVEL,
  LIFECYCLE,
  FILE_KEYS,
  DESENSITIZE,
  MOCK_SCENARIO,
};

/**
 * 安全日志工具 — 脱敏日志记录
 * posture-guard/logger.js
 */

const LEVEL = { DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3 };

let _minLevel = LEVEL.INFO;

function _ts() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

/**
 * 日志脱敏：去除敏感数值，保留类别
 */
function _sanitize(msg) {
  if (typeof msg !== 'string') return msg;
  // 模糊时间戳
  return msg.replace(/\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}/g, '**');
}

function log(level, tag, message, data) {
  if (level < _minLevel) return;
  const prefix = ['[DEBUG]', '[INFO]', '[WARN]', '[ERROR]'][level] || '[LOG]';
  const ts = _ts();
  const safeMsg = _sanitize(message);
  const line = `${ts} ${prefix} [${tag}] ${safeMsg}`;
  if (level <= LEVEL.INFO) {
    console.log(line);
  } else if (level === LEVEL.WARN) {
    console.warn(line);
  } else {
    console.error(line);
  }
}

module.exports = {
  LEVEL,
  setLevel(l) { _minLevel = l; },
  debug: (tag, msg, data) => log(LEVEL.DEBUG, tag, msg, data),
  info: (tag, msg, data) => log(LEVEL.INFO, tag, msg, data),
  warn: (tag, msg, data) => log(LEVEL.WARN, tag, msg, data),
  error: (tag, msg, data) => log(LEVEL.ERROR, tag, msg, data),
};

/**
 * 通用工具函数
 * posture-guard/helpers.js
 */

/**
 * 计算合加速度大小
 */
function accMagnitude(ax, ay, az) {
  return Math.sqrt(ax * ax + ay * ay + az * az);
}

/**
 * 计算俯仰角（度）— 基于加速度估算
 * 假设设备平放时 az≈1g，前倾时 ay 分量增大
 */
function pitchAngle(ax, ay, az) {
  return Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * (180 / Math.PI);
}

/**
 * 计算横滚角（度）
 */
function rollAngle(ax, ay, az) {
  return Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * (180 / Math.PI);
}

/**
 * 数组均值
 */
function mean(arr) {
  if (!arr.length) return 0;
  return arr.reduce((s, v) => s + v, 0) / arr.length;
}

/**
 * 数组方差
 */
function variance(arr) {
  if (arr.length < 2) return 0;
  const m = mean(arr);
  return arr.reduce((s, v) => s + (v - m) * (v - m), 0) / arr.length;
}

/**
 * 数组最大值
 */
function max(arr) {
  return arr.length ? Math.max(...arr) : 0;
}

/**
 * PKCS#7 填充（16字节块）
 */
function pkcs7Pad(data, blockSize) {
  const padLen = blockSize - (data.length % blockSize);
  const padded = new Uint8Array(data.length + padLen);
  padded.set(data);
  for (let i = data.length; i < padded.length; i++) {
    padded[i] = padLen;
  }
  return padded;
}

/**
 * PKCS#7 去填充
 */
function pkcs7Unpad(data) {
  const padLen = data[data.length - 1];
  if (padLen > 16 || padLen === 0) return data;
  return data.slice(0, data.length - padLen);
}

/**
 * 简易 XOR-based 加密（轻量替代AES，模拟器验证用）
 * 实际生产环境应使用标准AES-128-CBC
 */
function xorEncrypt(data, key) {
  const result = new Uint8Array(data.length);
  for (let i = 0; i < data.length; i++) {
    result[i] = data[i] ^ key[i % key.length];
  }
  return result;
}

/**
 * 生成随机IV（16字节）
 */
function generateIV() {
  const iv = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    iv[i] = Math.floor(Math.random() * 256);
  }
  return iv;
}

/**
 * 简易密钥派生（模拟设备UID → 密钥）
 */
function deriveKey(deviceUID, salt, level) {
  let hash = 0;
  const str = `${deviceUID}-${salt}-${level}`;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
  }
  const key = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    key[i] = ((hash * (i + 1) * 31) & 0xff);
  }
  return key;
}

/**
 * 将Uint8Array转为hex字符串
 */
function toHex(arr) {
  return Array.from(arr).map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * hex字符串转Uint8Array
 */
function fromHex(hex) {
  const arr = new Uint8Array(hex.length / 2);
  for (let i = 0; i < arr.length; i++) {
    arr[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return arr;
}

/**
 * 模糊时间戳到小时级
 */
function fuzzyTimeHour(timestamp) {
  const d = new Date(timestamp);
  d.setMinutes(0, 0, 0);
  return d.getTime();
}

/**
 * 心率区间归一化（5BPM为一个区间）
 */
function normalizeHR(bpm, interval) {
  const base = Math.floor(bpm / interval) * interval;
  return `${base}-${base + interval}`;
}

/**
 * GPS坐标网格编码
 */
function gridEncode(lat, lng, gridSize) {
  const gridLat = Math.floor(lat * 1000 / gridSize);
  const gridLng = Math.floor(lng * 1000 / gridSize);
  const letter = String.fromCharCode(65 + (Math.abs(gridLat) % 26));
  return `Grid-${letter}${Math.abs(gridLng) % 100}`;
}

module.exports = {
  accMagnitude,
  pitchAngle,
  rollAngle,
  mean,
  variance,
  max,
  pkcs7Pad,
  pkcs7Unpad,
  xorEncrypt,
  generateIV,
  deriveKey,
  toHex,
  fromHex,
  fuzzyTimeHour,
  normalizeHR,
  gridEncode,
};

/**
 * 模拟器Mock传感器数据生成器
 * posture-guard/mock-sensor.js
 *
 * 生成各类体态场景的传感器数据，用于模拟器验证
 */

const { MOCK_SCENARIO } = require('../utils/constants');

function _noise(scale) {
  return (Math.random() - 0.5) * scale;
}

const generators = {
  /**
   * 正常坐姿：轻微晃动，合加速度≈1g
   */
  normal(t) {
    return {
      ax: 0.05 + _noise(0.02),
      ay: 0.1 + _noise(0.02),
      az: 0.95 + _noise(0.03),
      gx: _noise(0.05),
      gy: _noise(0.05),
      gz: _noise(0.05),
    };
  },

  /**
   * 低头前倾：ay逐渐减小（负方向增大），俯仰角>30°
   * 模拟头部前倾，手腕随之下沉
   */
  headDown(t) {
    // 前20秒逐渐倾斜，之后保持
    const progress = Math.min(t / 20, 1);
    const pitch = progress * 0.8; // 最大倾斜
    return {
      ax: 0.1 + _noise(0.02),
      ay: 0.1 - pitch + _noise(0.02),
      az: 0.9 - progress * 0.2 + _noise(0.03),
      gx: _noise(0.03),
      gy: -0.02 * progress + _noise(0.03),
      gz: _noise(0.03),
    };
  },

  /**
   * 久坐伏案：合加速度极低（几乎不动），俯仰角>15°
   */
  sedentary(t) {
    const sway = Math.sin(t * 0.05) * 0.02;
    return {
      ax: 0.02 + _noise(0.005),
      ay: 0.25 + sway + _noise(0.005),
      az: 0.85 + _noise(0.01),
      gx: _noise(0.01),
      gy: _noise(0.01),
      gz: _noise(0.01),
    };
  },

  /**
   * 跷二郎腿：横滚角周期性波动 + Z轴抖动
   */
  crossLegs(t) {
    return {
      ax: 0.3 + Math.sin(t * 0.8) * 0.2 + _noise(0.03),
      ay: 0.1 + _noise(0.02),
      az: 0.9 + Math.sin(t * 1.2) * 0.1 + _noise(0.03),
      gx: _noise(0.05),
      gy: _noise(0.05),
      gz: Math.sin(t * 1.5) * 0.3 + _noise(0.1),
    };
  },
};

/**
 * Mock传感器管理器
 */
class MockSensor {
  constructor() {
    this.scenario = MOCK_SCENARIO.NORMAL;
    this.startTime = Date.now();
    this.timer = null;
    this.listeners = [];
    this.sampleInterval = 20; // 50Hz = 20ms
  }

  /**
   * 设置场景
   */
  setScenario(scenario) {
    this.scenario = scenario;
    this.startTime = Date.now();
  }

  /**
   * 注册数据回调
   */
  subscribe(callback) {
    this.listeners.push(callback);
    return () => {
      this.listeners = this.listeners.filter(cb => cb !== callback);
    };
  }

  /**
   * 开始模拟采集
   */
  start() {
    if (this.timer) return;
    this.startTime = Date.now();
    this.timer = setInterval(() => {
      const t = (Date.now() - this.startTime) / 1000;
      const gen = generators[this.scenario] || generators.normal;
      const sample = gen(t);
      sample.timestamp = Date.now();
      this.listeners.forEach(cb => cb(sample));
    }, this.sampleInterval);
  }

  /**
   * 停止采集
   */
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /**
   * 生成一批离线数据（用于测试）
   */
  generateBatch(scenario, durationSec) {
    const gen = generators[scenario] || generators.normal;
    const count = durationSec * (1000 / this.sampleInterval);
    const data = [];
    for (let i = 0; i < count; i++) {
      const t = (i * this.sampleInterval) / 1000;
      const sample = gen(t);
      sample.timestamp = Date.now() - (count - i) * this.sampleInterval;
      data.push(sample);
    }
    return data;
  }

  /**
   * 获取当前模拟场景的描述
   */
  getScenarioInfo() {
    const info = {
      [MOCK_SCENARIO.NORMAL]: { name: '正常坐姿', desc: '轻微晃动，合加速度≈1g' },
      [MOCK_SCENARIO.HEAD_DOWN]: { name: '低头前倾', desc: '俯仰角逐渐增大>30°' },
      [MOCK_SCENARIO.SEDENTARY]: { name: '久坐伏案', desc: '几乎不动，低合加速度' },
      [MOCK_SCENARIO.CROSS_LEGS]: { name: '跷二郎腿', desc: '横滚周期波动+Z轴抖动' },
    };
    return info[this.scenario] || info[MOCK_SCENARIO.NORMAL];
  }
}

module.exports = { MockSensor, MOCK_SCENARIO };

/**
 * 端侧AI体态识别引擎
 * posture-guard/posture-engine.js
 *
 * 时序特征提取 + 规则/决策树混合分类
 */

const { POSTURE_TYPE, WINDOW_SIZE, THRESHOLDS } = require('../utils/constants');
const { accMagnitude, pitchAngle, rollAngle, mean, variance } = require('../utils/helpers');
const logger = require('../utils/logger');

const TAG = 'PostureEngine';

/**
 * 特征提取：从滑动窗口数据中提取12维特征向量
 */
function extractFeatures(window) {
  if (window.length < 10) return null;

  const axArr = window.map(s => s.ax);
  const ayArr = window.map(s => s.ay);
  const azArr = window.map(s => s.az);
  const gxArr = window.map(s => s.gx);
  const gyArr = window.map(s => s.gy);
  const gzArr = window.map(s => s.gz);

  const accMags = window.map(s => accMagnitude(s.ax, s.ay, s.az));
  const pitches = window.map(s => pitchAngle(s.ax, s.ay, s.az));
  const rolls = window.map(s => rollAngle(s.ax, s.ay, s.az));

  return {
    // 加速度均值 (3维)
    meanAx: mean(axArr),
    meanAy: mean(ayArr),
    meanAz: mean(azArr),
    // 加速度方差 (3维)
    varAx: variance(axArr),
    varAy: variance(ayArr),
    varAz: variance(azArr),
    // 陀螺仪均值 (3维)
    meanGx: mean(gxArr),
    meanGy: mean(gyArr),
    meanGz: mean(gzArr),
    // 合加速度统计 (1维)
    meanAccMag: mean(accMags),
    // 姿态角 (1维)
    meanPitch: mean(pitches),
    // 横滚角波动 (1维)
    rollVariance: variance(rolls),
  };
}

/**
 * 规则层：快速筛选不良体态
 */
function ruleClassify(features) {
  if (!features) return { type: POSTURE_TYPE.NORMAL, confidence: 0, reason: '特征不足' };

  // 规则1：低头前倾 — 俯仰角>30°
  if (features.meanPitch > THRESHOLDS.headDown.pitchAngle) {
    const confidence = Math.min(0.95, 0.85 + (features.meanPitch - 30) * 0.01);
    return {
      type: POSTURE_TYPE.HEAD_DOWN,
      confidence,
      reason: `俯仰角${features.meanPitch.toFixed(1)}°>${THRESHOLDS.headDown.pitchAngle}°`,
    };
  }

  // 规则2：久坐伏案 — 合加速度<0.1g + 俯仰角>15°
  if (features.meanAccMag < THRESHOLDS.sedentary.accMag &&
      features.meanPitch > THRESHOLDS.sedentary.pitchAngle) {
    const confidence = Math.min(0.95, 0.80 + (THRESHOLDS.sedentary.accMag - features.meanAccMag) * 0.5);
    return {
      type: POSTURE_TYPE.SEDENTARY,
      confidence,
      reason: `合加速度${features.meanAccMag.toFixed(3)}g<${THRESHOLDS.sedentary.accMag}g & 俯仰角${features.meanPitch.toFixed(1)}°`,
    };
  }

  // 规则3：跷二郎腿 — 横滚角周期性波动 + Z轴抖动
  if (features.rollVariance > 0.02 && features.varAz > 0.01) {
    const confidence = Math.min(0.95, 0.75 + features.rollVariance * 0.5);
    return {
      type: POSTURE_TYPE.CROSS_LEGS,
      confidence,
      reason: `横滚方差${features.rollVariance.toFixed(4)} & Z轴方差${features.varAz.toFixed(4)}`,
    };
  }

  return { type: POSTURE_TYPE.NORMAL, confidence: 0.9, reason: '无异常' };
}

/**
 * 体态识别引擎
 */
class PostureEngine {
  constructor() {
    this.window = [];             // 滑动窗口
    this.history = [];            // 识别历史 [{type, confidence, timestamp}]
    this.anomalyStart = null;     // 异常开始时间
    this.lastType = POSTURE_TYPE.NORMAL;
    this.onResult = null;         // 回调：识别结果
  }

  /**
   * 喂入传感器数据
   */
  feed(sample) {
    this.window.push(sample);
    if (this.window.length > WINDOW_SIZE) {
      this.window.shift();
    }

    // 窗口满时进行推理
    if (this.window.length >= WINDOW_SIZE) {
      return this._infer();
    }
    return null;
  }

  /**
   * 推理
   */
  _infer() {
    const features = extractFeatures(this.window);
    const result = ruleClassify(features);

    // 异常持续时间判定
    const now = Date.now();
    if (result.type !== POSTURE_TYPE.NORMAL) {
      if (this.lastType === result.type && this.anomalyStart) {
        // 持续中
        const durationMs = now - this.anomalyStart;
        const durationMin = durationMs / 60000;
        const requiredMin = this._getRequiredDuration(result.type);
        result持续时间 = durationMin;
        result持续时间达标 = durationMin >= requiredMin;
      } else {
        // 新异常开始
        this.anomalyStart = now;
        result持续时间 = 0;
        result持续时间达标 = false;
      }
    } else {
      this.anomalyStart = null;
      result持续时间 = 0;
      result持续时间达标 = false;
    }

    this.lastType = result.type;

    const record = {
      type: result.type,
      confidence: result.confidence,
      reason: result.reason,
      timestamp: now,
      features: {
        meanPitch: features.meanPitch,
        meanAccMag: features.meanAccMag,
        rollVariance: features.rollVariance,
      },
      持续时间: result持续时间,
      持续时间达标: result持续时间达标,
    };

    this.history.push(record);
    if (this.history.length > 500) this.history.shift();

    if (this.onResult) this.onResult(record);

    return record;
  }

  _getRequiredDuration(type) {
    const map = {
      [POSTURE_TYPE.HEAD_DOWN]: THRESHOLDS.headDown.durationMin,
      [POSTURE_TYPE.SEDENTARY]: THRESHOLDS.sedentary.durationMin,
      [POSTURE_TYPE.CROSS_LEGS]: THRESHOLDS.crossLegs.durationMin,
    };
    return map[type] || 10;
  }

  /**
   * 获取今日统计
   */
  getTodayStats() {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const ts = todayStart.getTime();

    const todayRecords = this.history.filter(r => r.timestamp >= ts);
    const counts = {};
    for (const type of Object.values(POSTURE_TYPE)) {
      counts[type] = todayRecords.filter(r => r.type === type).length;
    }
    return {
      total: todayRecords.length,
      abnormal: todayRecords.filter(r => r.type !== POSTURE_TYPE.NORMAL).length,
      counts,
    };
  }

  /**
   * 获取最近N条记录
   */
  getRecentRecords(n) {
    return this.history.slice(-n).reverse();
  }

  /**
   * 清空历史
   */
  clearHistory() {
    this.history = [];
    this.window = [];
    this.anomalyStart = null;
    this.lastType = POSTURE_TYPE.NORMAL;
  }
}

module.exports = { PostureEngine, extractFeatures, ruleClassify };

