/**
 * 数据脱敏引擎
 * posture-guard/desensitizer.js
 *
 * 对敏感字段进行模糊化、匿名化处理，保留有效特征
 */

const { DESENSITIZE } = require('../utils/constants');
const { fuzzyTimeHour, normalizeHR, gridEncode } = require('../utils/helpers');
const logger = require('../utils/logger');

const TAG = 'Desensitizer';

const rules = {
  /**
   * 时间戳脱敏：精确时间 → 小时级模糊
   */
  timestamp: {
    type: 'TIME_FUZZY',
    process(ts) {
      return fuzzyTimeHour(ts);
    },
    format(ts) {
      const d = new Date(ts);
      const pad = n => String(n).padStart(2, '0');
      return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:00`;
    },
  },

  /**
   * 心率脱敏：精确BPM → 区间归一化
   */
  heartRate: {
    type: 'INTERVAL_NORMALIZE',
    process(bpm) {
      return normalizeHR(bpm, DESENSITIZE.HR_INTERVAL);
    },
  },

  /**
   * GPS坐标脱敏：精确坐标 → 网格编码
   */
  gpsCoordinate: {
    type: 'GRID_ENCODE',
    process(lat, lng) {
      return gridEncode(lat, lng, DESENSITIZE.GRID_SIZE);
    },
  },

  /**
   * 步数脱敏：精确步数 → 百位取整
   */
  stepCount: {
    type: 'ROUND',
    process(steps) {
      return Math.floor(steps / 100) * 100;
    },
  },

  /**
   * 加速度数据：保留原始值（体态分析必需）
   */
  acceleration: {
    type: 'PRESERVE',
    process(value) {
      return Math.round(value * 100) / 100; // 保留2位精度
    },
  },
};

/**
 * 脱敏引擎
 */
const desensitizer = {
  /**
   * 脱敏心率数据
   * 输入: [{bpm, timestamp}]
   * 输出: [{hrRange, fuzzyTime}]
   */
  processHeartRate(records) {
    return records.map(r => ({
      hrRange: rules.heartRate.process(r.bpm),
      fuzzyTime: rules.timestamp.format(r.timestamp),
      rawTimestamp: r.timestamp,
    }));
  },

  /**
   * 脱敏步数数据
   */
  processStepCount(records) {
    return records.map(r => ({
      steps: rules.stepCount.process(r.steps),
      fuzzyTime: rules.timestamp.format(r.timestamp),
      rawTimestamp: r.timestamp,
    }));
  },

  /**
   * 脱敏GPS轨迹
   */
  processGPSTrack(points) {
    return points.map(p => ({
      gridCode: rules.gpsCoordinate.process(p.lat, p.lng),
      fuzzyTime: rules.timestamp.format(p.timestamp),
    }));
  },

  /**
   * 脱敏传感器姿态数据（保留特征）
   */
  processSensorData(samples) {
    return samples.map(s => ({
      ax: rules.acceleration.process(s.ax),
      ay: rules.acceleration.process(s.ay),
      az: rules.acceleration.process(s.az),
      timestamp: s.timestamp,
    }));
  },

  /**
   * 生成脱敏对比数据（用于安全中心展示）
   */
  generateComparison(heartRate) {
    const original = {
      bpm: heartRate,
      timestamp: Date.now(),
    };
    const desensitized = {
      hrRange: rules.heartRate.process(heartRate),
      fuzzyTime: rules.timestamp.format(Date.now()),
    };
    return { original, desensitized };
  },

  rules,
};

module.exports = desensitizer;

/**
 * AES分级加密存储引擎
 * posture-guard/crypto-engine.js
 *
 * 分级加密策略 + 密钥派生 + 数据生命周期管理
 */

const { CRYPTO_LEVEL, LIFECYCLE, FILE_KEYS } = require('../utils/constants');
const { xorEncrypt, generateIV, deriveKey, toHex, fromHex, pkcs7Pad, pkcs7Unpad } = require('../utils/helpers');
const logger = require('../utils/logger');

const TAG = 'CryptoEngine';

// 设备UID（模拟器环境使用固定值）
const DEVICE_UID = 'openvela-sim-2026';

// 密钥层级配置
const keyHierarchy = {
  [CRYPTO_LEVEL.L1]: {
    salt: 'posture-stats-salt',
    key: null,
  },
  [CRYPTO_LEVEL.L2]: {
    salt: 'health-privacy-salt',
    key: null,
  },
};

/**
 * 初始化密钥
 */
function initKeys() {
  for (const [level, cfg] of Object.entries(keyHierarchy)) {
    cfg.key = deriveKey(DEVICE_UID, cfg.salt, level);
    logger.info(TAG, `密钥初始化: ${level}`);
  }
}

/**
 * 加密数据
 * @param {string} plaintext - 明文JSON字符串
 * @param {string} level - 加密等级 L1/L2
 * @returns {{ciphertext: string, iv: string, level: string}}
 */
function encrypt(plaintext, level) {
  if (!keyHierarchy[level].key) initKeys();

  const key = keyHierarchy[level].key;
  const iv = generateIV();

  // 转为Uint8Array
  const encoder = new TextEncoder();
  const data = encoder.encode(plaintext);

  // PKCS#7填充
  const padded = pkcs7Pad(data, 16);

  // 加密（XOR模拟，实际应使用AES-128-CBC）
  const encrypted = xorEncrypt(padded, key);

  // 模拟IV混淆
  const ivXored = xorEncrypt(iv, key);

  return {
    ciphertext: toHex(encrypted),
    iv: toHex(ivXored),
    level,
  };
}

/**
 * 解密数据
 */
function decrypt(encryptedData) {
  const { ciphertext, iv, level } = encryptedData;
  if (!keyHierarchy[level].key) initKeys();

  const key = keyHierarchy[level].key;

  // 还原IV
  const ivBytes = xorEncrypt(fromHex(iv), key);

  // 解密
  const cipherBytes = fromHex(ciphertext);
  const decrypted = xorEncrypt(cipherBytes, key);

  // 去填充
  const unpadded = pkcs7Unpad(decrypted);

  // 转字符串
  const decoder = new TextDecoder();
  return decoder.decode(unpadded);
}

/**
 * 获取加密统计信息
 */
function getEncryptionStats() {
  return {
    deviceUID: DEVICE_UID.substring(0, 8) + '***',
    levels: Object.keys(keyHierarchy).map(level => ({
      level,
      algorithm: 'AES-128-CBC (XOR-SIM)',
      keySource: 'Device UID Derived',
      keyLength: '128-bit',
    })),
  };
}

/**
 * 初始化
 */
initKeys();

module.exports = {
  encrypt,
  decrypt,
  getEncryptionStats,
  CRYPTO_LEVEL,
};

/**
 * 加密存储管理器
 * posture-guard/storage-manager.js
 *
 * 加密存储 + 数据生命周期管理 + 自动销毁
 */

const { CRYPTO_LEVEL, LIFECYCLE, FILE_KEYS } = require('../utils/constants');
const cryptoEngine = require('./crypto-engine');
const logger = require('../utils/logger');

const TAG = 'StorageManager';

/**
 * 内存模拟存储（模拟器环境替代文件系统）
 */
const _store = {};

/**
 * 存储管理器
 */
const storageManager = {
  /**
   * 保存加密数据
   * @param {string} key - 存储键名
   * @param {*} data - 要保存的数据
   * @param {object} options - {level, expiryDays}
   */
  save(key, data, options = {}) {
    const { level = CRYPTO_LEVEL.L1, expiryDays } = options;
    const retention = expiryDays || LIFECYCLE[key] || LIFECYCLE.postureStats;

    const serialized = JSON.stringify(data);
    const encrypted = cryptoEngine.encrypt(serialized, level);

    const record = {
      ...encrypted,
      metadata: {
        createTime: Date.now(),
        expiryTime: Date.now() + retention * 86400000,
        level,
        dataType: key,
      },
    };

    _store[key] = record;
    logger.info(TAG, `保存加密数据: ${key} (等级:${level}, 保留:${retention}天)`);
    return true;
  },

  /**
   * 读取并解密数据
   * @param {string} key - 存储键名
   * @returns {{expired: boolean, data: *}}
   */
  load(key) {
    const record = _store[key];
    if (!record) {
      return { expired: false, data: null };
    }

    // 检查是否过期
    if (Date.now() > record.metadata.expiryTime) {
      logger.warn(TAG, `数据已过期: ${key}`);
      return { expired: true, data: null };
    }

    try {
      const decrypted = cryptoEngine.decrypt(record);
      const data = JSON.parse(decrypted);
      return { expired: false, data };
    } catch (e) {
      logger.error(TAG, `解密失败: ${key} - ${e.message}`);
      return { expired: false, data: null };
    }
  },

  /**
   * 删除数据（覆写清零）
   */
  remove(key) {
    if (_store[key]) {
      // 覆写清零
      _store[key] = {
        ciphertext: '00'.repeat(32),
        iv: '00'.repeat(16),
        level: 'L1',
        metadata: { createTime: 0, expiryTime: 0, level: 'L1', dataType: key },
      };
      delete _store[key];
      logger.info(TAG, `安全删除: ${key}`);
    }
  },

  /**
   * 执行自动清理（检查所有过期数据）
   * @returns {string[]} 被清理的键名列表
   */
  autoCleanup() {
    const cleaned = [];
    const now = Date.now();

    for (const [key, record] of Object.entries(_store)) {
      if (record.metadata && now > record.metadata.expiryTime) {
        this.remove(key);
        cleaned.push(key);
      }
    }

    if (cleaned.length > 0) {
      logger.info(TAG, `自动清理完成: ${cleaned.join(', ')}`);
    }
    return cleaned;
  },

  /**
   * 获取所有数据的生命周期状态
   */
  getLifecycleStatus() {
    const status = [];
    const now = Date.now();

    for (const [key, record] of Object.entries(_store)) {
      if (!record.metadata) continue;
      const total = record.metadata.expiryTime - record.metadata.createTime;
      const elapsed = now - record.metadata.createTime;
      const remaining = Math.max(0, record.metadata.expiryTime - now);

      status.push({
        key,
        level: record.metadata.level,
        createTime: record.metadata.createTime,
        expiryTime: record.metadata.expiryTime,
        remainingDays: Math.ceil(remaining / 86400000),
        progress: Math.min(1, elapsed / total),
        expired: now > record.metadata.expiryTime,
      });
    }
    return status;
  },

  /**
   * 获取存储统计
   */
  getStorageStats() {
    let totalSize = 0;
    let count = 0;
    for (const record of Object.values(_store)) {
      if (record.ciphertext) {
        totalSize += record.ciphertext.length / 2; // hex → bytes
        count++;
      }
    }
    return {
      count,
      totalSizeBytes: totalSize,
      totalSizeKB: (totalSize / 1024).toFixed(1),
    };
  },

  /**
   * 清空所有数据
   */
  clearAll() {
    for (const key of Object.keys(_store)) {
      this.remove(key);
    }
    logger.info(TAG, '所有数据已清空');
  },
};

module.exports = storageManager;

/**
 * 提醒管理器
 * posture-guard/reminder-manager.js
 *
 * 震动提醒 + 弹窗提醒 + 冷却时间控制
 */

const { POSTURE_LABELS, REMINDER_COOLDOWN_MS } = require('../utils/constants');
const logger = require('../utils/logger');

const TAG = 'ReminderManager';

/**
 * 提醒管理器
 */
class ReminderManager {
  constructor() {
    this.lastReminderTime = {};  // {type: timestamp}
    this.reminderLog = [];       // 提醒历史
    this.onReminder = null;      // 回调：{type, message, timestamp}
    this.vibrator = null;        // 震动服务引用
    this.dialog = null;          // 弹窗服务引用
  }

  /**
   * 注册系统服务
   */
  setServices(vibrator, dialog) {
    this.vibrator = vibrator;
    this.dialog = dialog;
  }

  /**
   * 检查并触发提醒
   * @param {object} postureResult - 体态识别结果
   * @returns {boolean} 是否触发了提醒
   */
  checkAndTrigger(postureResult) {
    if (!postureResult || !postureResult.durationReady) return false;

    const { type, confidence } = postureResult;

    // 置信度校验
    const minConfidence = { HEAD_DOWN: 0.85, SEDENTARY: 0.80, CROSS_LEGS: 0.75 };
    if (confidence < (minConfidence[type] || 0.75)) return false;

    // 冷却时间检查
    const now = Date.now();
    const lastTime = this.lastReminderTime[type] || 0;
    if (now - lastTime < REMINDER_COOLDOWN_MS) return false;

    // 触发提醒
    this._trigger(type, confidence);
    this.lastReminderTime[type] = now;
    return true;
  }

  /**
   * 执行提醒
   */
  _trigger(type, confidence) {
    const label = POSTURE_LABELS[type] || '未知异常';
    const messages = {
      HEAD_DOWN: `检测到${label}，请抬头活动颈椎`,
      SEDENTARY: `检测到${label}，已持续较长时间，请起身活动`,
      CROSS_LEGS: `检测到${label}，请注意调整坐姿`,
    };
    const message = messages[type] || `检测到${label}`;

    const record = {
      type,
      label,
      message,
      confidence,
      timestamp: Date.now(),
    };

    this.reminderLog.push(record);
    if (this.reminderLog.length > 100) this.reminderLog.shift();

    logger.warn(TAG, `提醒触发: ${label} (置信度:${(confidence * 100).toFixed(0)}%)`);

    // 震动提醒
    this._vibrate();

    // 弹窗提醒
    this._showDialog(label, message);

    // 通知回调
    if (this.onReminder) this.onReminder(record);
  }

  _vibrate() {
    try {
      if (this.vibrator && this.vibrator.vibrate) {
        this.vibrator.vibrate({ mode: 'short' });
      } else {
        logger.info(TAG, '震动: [模拟] 200ms短震动');
      }
    } catch (e) {
      logger.warn(TAG, `震动失败: ${e.message}`);
    }
  }

  _showDialog(title, message) {
    try {
      if (this.dialog && this.dialog.show) {
        this.dialog.show({
          title: '体态提醒',
          message,
          buttons: [{ text: '知道了', style: 'default' }],
        });
      } else {
        logger.info(TAG, `弹窗: [${title}] ${message}`);
      }
    } catch (e) {
      logger.warn(TAG, `弹窗失败: ${e.message}`);
    }
  }

  /**
   * 获取提醒历史
   */
  getHistory(n) {
    return this.reminderLog.slice(-n).reverse();
  }

  /**
   * 获取今日提醒统计
   */
  getTodayStats() {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const ts = todayStart.getTime();
    return this.reminderLog.filter(r => r.timestamp >= ts);
  }

  clearHistory() {
    this.reminderLog = [];
    this.lastReminderTime = {};
  }
}

module.exports = ReminderManager;

